  ('27ed0cf6-481d-5288-b55d-e6ce02c06d39', '2026-09', 'mkt', 5, '{"cliente": "CU Canada", "bbdd": "150", "email": "150", "paid": "150", "descripcion": "Creamos una base de datos de al menos 300 contactos por mes, una campaña de email mkt de 3 envios a esa BBDD y generamos la estrategia, implementacion y optimizacion de paid media para la certificacion/servicio que el cliente quiera hacer foco. Incluye optimizacion continua, donde revisamos las metricas y rendimiento de las diferentes palabras clave"}'::jsonb, 'Carga inicial (Excel)'),
  ('3f8ed6a8-0a43-5519-ae52-c670fdcc3b70', '2026-09', 'mkt_libre', 0, '{"A1": "FELO: Porfa detallame acá cada uno y cuando corresponda agregar fecha limite de renovación \nPoner siglas empresa (PS/CU) + país + sector (si aplica)", "A2": "Estas acciones SOLO se \"cargan\" en esta solapa, no se duplican en la de \"Variables\".   La facturación la hace Agus en la solapa Fijo", "A5": "Plan de campañas recurrente", "A6": "Campaña se pienza por programa/norma/tema", "A7": "Campaña dura minimo 6 meses/ lo mas seguro es que se prolongue si vemos resultados", "A8": "mes 1 optimizacion y bbdd (minimo 300 contactos) por programa", "D8": "precio: 200 + 200", "A9": "mes 1 arranca paid media si o si de todos las campañas que se quieran.  Meses 2 y hasta 6.  optimizacion contiua (metricas, rendimiento de palabras clave)", "A10": "mes 2 campañas mailing si esta bbdd lista ser arranca sino no (3 mails por mes a esa bbdd)", "A12": "Paso 1", "A13": "opt web", "B13": "200", "A15": "Campaña 1: Primus", "B15": "Mayo", "C15": "Junio", "D15": "Julio", "A16": "bbdd", "B16": "200", "A17": "campaña paid media", "B17": "60", "C17": "60", "D17": "60", "A18": "no incluye inv.", "B18": "1eur", "C18": "2 eur", "D18": "2 o + eur", "A19": "campaña mailing", "B19": "150", "A20": "Combo", "B20": "350", "A22": "Campaña 2: Aqua", "A23": "bbdd", "C23": "200", "A24": "campaña paid media", "B24": "60", "C24": "60", "D24": "60", "A25": "no incluye inv.", "B25": "1eur", "A26": "campaña mailing", "C26": "150", "A27": "Combo", "B27": "60", "C29": "120", "D29": "120", "A32": "Campaña 2: Aqua", "A33": "bbdd", "D33": "200", "A34": "campaña paid media", "B34": "60", "C34": "60", "D34": "60", "A35": "no incluye inv.", "D35": "1eur", "A36": "campaña mailing", "D36": "150", "A37": "Combo", "D37": "350"}'::jsonb, 'Carga inicial (Excel)'),
